const mode=new URLSearchParams(location.search).get('mode')||'dropdown';
const groups=[{key:'year',name:'Year'},{key:'services',name:'Service'},{key:'industry',name:'Industry'}];
let projects=[],active={year:[],services:[],industry:[]},draft=null,open=null,drawerOpen='services',view='list';
const controls=document.querySelector('#controls'),results=document.querySelector('#results'),status=document.querySelector('#status'),dialog=document.querySelector('dialog');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const chevron='<svg class="chevron" viewBox="0 0 12 12" fill="none" aria-hidden="true"><path d="m2 4 4 4 4-4" stroke="currentColor"/></svg>';
const check='<svg class="check" viewBox="0 0 12 12" fill="none" aria-hidden="true"><path d="m1.5 6 3 3 6-6" stroke="currentColor"/></svg>';
const count=f=>Object.values(f).reduce((n,a)=>n+a.length,0);
const options=key=>[...new Set(projects.flatMap(p=>p[key]))].sort((a,b)=>key==='year'?b.localeCompare(a):a.localeCompare(b));
const filtered=f=>projects.filter(p=>groups.every(g=>!f[g.key].length||f[g.key].some(v=>Array.isArray(p[g.key])?p[g.key].includes(v):p[g.key]===v)));
const summary=(f,key)=>f[key].length===0?'All':f[key].length===1?f[key][0]:f[key].length+' selected';
function choices(key,f,isDraft=false){return '<div class="choices">'+['All',...options(key)].map((v,i)=>{const selected=v==='All'?!f[key].length:f[key].includes(v);return `<button id="${isDraft?'d':'c'}-${key}-${i}" class="choice" aria-pressed="${selected}" data-action="choose" data-key="${key}" data-value="${esc(v)}" ${isDraft?'data-draft="true"':''}><span>${esc(v)}</span>${selected?check:''}</button>`}).join('')+'</div>'}
function accordion(f,expanded,isDraft=false){return `<div class="accordion">${groups.map(g=>`<div class="category-row"><button id="${isDraft?'drawer':'row'}-${g.key}" class="category-toggle" data-action="${isDraft?'drawer-category':'category'}" data-key="${g.key}" aria-expanded="${expanded===g.key}" aria-controls="${isDraft?'d':'a'}-${g.key}"><span class="name">/ ${g.name}</span><span class="row-value">${esc(summary(f,g.key))}</span>${chevron}</button>${expanded===g.key?`<div id="${isDraft?'d':'a'}-${g.key}">${choices(g.key,f,isDraft)}</div>`:''}</div>`).join('')}</div>`}
function viewToggle(){return `<div class="view" aria-label="Project view"><button id="view-grid" data-action="view" data-value="grid" aria-pressed="${view==='grid'}">Grid</button><span aria-hidden="true">/</span><button id="view-list" data-action="view" data-value="list" aria-pressed="${view==='list'}">List</button></div>`}
function renderControls(){const focus=document.activeElement?.id;let filters='';if(mode==='accordion')filters=accordion(active,open);if(mode==='dropdown')filters=`<div class="dropdown-wrap"><div class="dropdown-triggers">${groups.map(g=>`<button id="trigger-${g.key}" class="dropdown-trigger" data-action="category" data-key="${g.key}" aria-expanded="${open===g.key}" aria-controls="filter-options"><span>${g.name}${active[g.key].length?' ('+active[g.key].length+')':''}</span>${chevron}</button>`).join('')}</div>${open?`<section id="filter-options" class="popover" aria-label="Filter by ${groups.find(g=>g.key===open).name}">${choices(open,active)}<div class="popover-footer"><button id="popover-reset" data-action="clear-category" data-key="${open}">Reset</button><button data-action="done">Done</button></div></section>`:''}</div>`;controls.innerHTML=filters+`<div class="toolbar ${mode==='sheet'?'sheet-toolbar':''}">${mode==='sheet'?`<button id="open-filters" class="filter-button" data-action="drawer"><svg class="filter-icon" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M1 4h14M1 12h14M5 1v6M11 9v6" stroke="currentColor"/></svg>Filters${count(active)?' ('+count(active)+')':''}</button>`:`<button class="clear" data-action="clear" ${count(active)?'':'disabled'}>Clear filters</button>`}${viewToggle()}</div>`;if(focus)document.getElementById(focus)?.focus({preventScroll:true})}
function renderResults(){const rows=filtered(active);status.innerHTML=`<span>${rows.length} ${rows.length===1?'project':'projects'}</span><span class="filter-summary">${count(active)?count(active)+' active '+(count(active)===1?'filter':'filters'):''}</span>`;if(!rows.length){results.innerHTML='<div class="empty">No projects match these filters.<button data-action="clear">Clear filters</button></div>';return}if(view==='grid'){results.innerHTML='<div class="project-grid">'+rows.map((p,i)=>`<article><a href="${esc(p.url)}" target="_blank" rel="noopener"><div class="project-heading"><span>${i+1}</span><span>/</span><span>${esc(p.title)}</span></div><img src="${esc(p.image)}&scale-down-to=800" alt="${esc(p.title)} project thumbnail" loading="lazy" width="800" height="450"></a><p class="services">${p.services.map(esc).join(' / ')}</p></article>`).join('')+'</div>'}else{results.innerHTML='<div class="project-list">'+[...rows].sort((a,b)=>b.year.localeCompare(a.year)||a.title.localeCompare(b.title)).map(p=>`<a href="${esc(p.url)}" target="_blank" rel="noopener"><span class="title">${esc(p.title)}</span><span class="year">${p.year}</span></a>`).join('')+'</div>'}}
function renderDrawer(){const focus=document.activeElement?.id;document.querySelector('#drawer').innerHTML=`<div class="drawer-head"><h2 id="drawer-title">Filters</h2><button data-action="cancel">Cancel</button></div><div class="drawer-body">${accordion(draft,drawerOpen,true)}</div><div class="drawer-foot"><button id="drawer-reset" class="reset" data-action="draft-reset">Reset</button><button class="apply" data-action="apply">Show ${filtered(draft).length} projects</button></div>`;if(focus)document.getElementById(focus)?.focus({preventScroll:true})}
function render(){renderControls();renderResults()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b){if(open&&mode==='dropdown'&&!e.target.closest('.dropdown-wrap')){open=null;renderControls()}return}const a=b.dataset.action,key=b.dataset.key,value=b.dataset.value;if(a==='category'){open=open===key?null:key;renderControls()}else if(a==='choose'){const f=b.dataset.draft?draft:active;if(value==='All')f[key]=[];else f[key]=f[key].includes(value)?f[key].filter(v=>v!==value):[...f[key],value];if(b.dataset.draft)renderDrawer();else render()}else if(a==='view'){view=value;open=null;render()}else if(a==='clear'){active={year:[],services:[],industry:[]};render();document.getElementById(mode==='sheet'?'open-filters':mode==='accordion'?'row-year':'trigger-year')?.focus({preventScroll:true})}else if(a==='clear-category'){active[key]=[];render()}else if(a==='done'){const k=open;open=null;renderControls();document.getElementById((mode==='accordion'?'row-':'trigger-')+k)?.focus()}else if(a==='drawer'){draft=structuredClone(active);drawerOpen='services';renderDrawer();dialog.showModal()}else if(a==='drawer-category'){drawerOpen=drawerOpen===key?null:key;renderDrawer()}else if(a==='draft-reset'){draft={year:[],services:[],industry:[]};renderDrawer()}else if(a==='apply'){active=structuredClone(draft);dialog.close();render()}else if(a==='cancel'){dialog.close()} });
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&open){const k=open;open=null;renderControls();document.getElementById((mode==='accordion'?'row-':'trigger-')+k)?.focus()}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.data?.view){view=e.data.view;render()}});
fetch('projects.json').then(r=>{if(!r.ok)throw Error('Project data could not load');return r.json()}).then(data=>{projects=data;render()}).catch(()=>{results.innerHTML='<p class="empty">The local project snapshot could not load. Reload this preview.</p>'});
